def main() -> int:
    candidates = json.loads((ROOT / "data/gtm_case_funnel_v2/candidates.json").read_text(encoding="utf-8"))
    queue = compile_mechanism_review_queue(candidates, DRAFTS)
    verify_mechanism_review_queue(queue)
    queue_path = ROOT / "evidence/v10/gtm-mechanism-review-queue-v2.json"
    atomic_write_text(queue_path, json.dumps(queue, ensure_ascii=False, indent=2, sort_keys=True) + "\n")
    empty_promoted = promote_approved_mechanisms(queue, [])
    promoted_path = ROOT / "data/gtm_case_funnel_v2/mechanism_audits.json"
    atomic_write_text(promoted_path, json.dumps(empty_promoted, ensure_ascii=False, indent=2, sort_keys=True) + "\n")
    print(json.dumps({"queue": str(queue_path), "review_item_count": queue["review_item_count"], "pending_human_review_count": queue["pending_human_review_count"], "mechanism_quota_credit": queue["mechanism_quota_credit"], "promoted_output": str(promoted_path)}, ensure_ascii=False, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
